-- AI Smart Healthcare System: MySQL 8 schema (generated by scripts/export_schema.py)
CREATE DATABASE IF NOT EXISTS smart_healthcare CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_healthcare;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS model_versions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	disease VARCHAR(20) NOT NULL, 
	algorithm VARCHAR(40) NOT NULL, 
	version VARCHAR(30) NOT NULL, 
	data_source VARCHAR(255), 
	n_samples INTEGER, 
	accuracy FLOAT, 
	precision_score FLOAT, 
	recall FLOAT, 
	f1 FLOAT, 
	roc_auc FLOAT, 
	confusion_matrix JSON, 
	is_best BOOL, 
	is_active BOOL, 
	trained_at DATETIME, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_model_versions_disease ON model_versions (disease);
CREATE INDEX ix_model_versions_is_active ON model_versions (is_active);
CREATE INDEX ix_model_versions_version ON model_versions (version);

CREATE TABLE IF NOT EXISTS users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(100) NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	`role` VARCHAR(10) NOT NULL, 
	created_at DATETIME, 
	PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_users_role ON users (`role`);

CREATE TABLE IF NOT EXISTS doctors (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	specialization VARCHAR(80), 
	experience_years INTEGER, 
	bio TEXT, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_doctors_specialization ON doctors (specialization);

CREATE TABLE IF NOT EXISTS feedback (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER, 
	message TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS patients (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	age INTEGER, 
	gender VARCHAR(10), 
	height_cm FLOAT, 
	weight_kg FLOAT, 
	chat_context_consent BOOL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS appointments (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	doctor_id INTEGER NOT NULL, 
	scheduled_at DATETIME NOT NULL, 
	reason VARCHAR(255), 
	status VARCHAR(12), 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_appointments_doctor_id ON appointments (doctor_id);
CREATE INDEX ix_appointments_patient_id ON appointments (patient_id);

CREATE TABLE IF NOT EXISTS chatbot_conversations (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	title VARCHAR(120), 
	language VARCHAR(5), 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_chatbot_conversations_patient_id ON chatbot_conversations (patient_id);
CREATE INDEX ix_chatbot_conversations_updated_at ON chatbot_conversations (updated_at);

CREATE TABLE IF NOT EXISTS diet_plans (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	goal VARCHAR(20), 
	bmi FLOAT, 
	bmr FLOAT, 
	tdee FLOAT, 
	calories INTEGER, 
	protein_g INTEGER, 
	carbs_g INTEGER, 
	fat_g INTEGER, 
	water_ml INTEGER, 
	inputs JSON, 
	warnings JSON, 
	is_active BOOL, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_diet_plans_created_at ON diet_plans (created_at);
CREATE INDEX ix_diet_plans_is_active ON diet_plans (is_active);
CREATE INDEX ix_diet_plans_patient_id ON diet_plans (patient_id);

CREATE TABLE IF NOT EXISTS disease_predictions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	disease VARCHAR(20) NOT NULL, 
	model_name VARCHAR(40), 
	model_version_id INTEGER, 
	risk_percent FLOAT NOT NULL, 
	risk_level VARCHAR(10) NOT NULL, 
	top_factors JSON, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(model_version_id) REFERENCES model_versions (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_disease_predictions_created_at ON disease_predictions (created_at);
CREATE INDEX ix_disease_predictions_disease ON disease_predictions (disease);
CREATE INDEX ix_disease_predictions_patient_id ON disease_predictions (patient_id);

CREATE TABLE IF NOT EXISTS health_analytics (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	analysis_type VARCHAR(30) NOT NULL, 
	period_start DATE, 
	period_end DATE, 
	result JSON, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_health_analytics_analysis_type ON health_analytics (analysis_type);
CREATE INDEX ix_health_analytics_created_at ON health_analytics (created_at);
CREATE INDEX ix_health_analytics_patient_id ON health_analytics (patient_id);

CREATE TABLE IF NOT EXISTS health_metrics (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	recorded_at DATETIME NOT NULL, 
	systolic FLOAT, 
	diastolic FLOAT, 
	blood_sugar FLOAT, 
	heart_rate FLOAT, 
	weight_kg FLOAT, 
	cholesterol FLOAT, 
	source VARCHAR(20), 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_health_metrics_patient_id ON health_metrics (patient_id);
CREATE INDEX ix_health_metrics_patient_time ON health_metrics (patient_id, recorded_at);
CREATE INDEX ix_health_metrics_recorded_at ON health_metrics (recorded_at);

CREATE TABLE IF NOT EXISTS medical_reports (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER, 
	title VARCHAR(120), 
	filename VARCHAR(200), 
	original_name VARCHAR(200), 
	file_type VARCHAR(10), 
	size_bytes INTEGER, 
	sha256 VARCHAR(64), 
	report_date DATE, 
	ocr_text LONGTEXT, 
	extraction_method VARCHAR(30), 
	status VARCHAR(20), 
	value_count INTEGER, 
	abnormal_count INTEGER, 
	uploaded_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_medical_reports_patient_id ON medical_reports (patient_id);
CREATE INDEX ix_medical_reports_report_date ON medical_reports (report_date);
CREATE INDEX ix_medical_reports_uploaded_at ON medical_reports (uploaded_at);

CREATE TABLE IF NOT EXISTS medicines (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER, 
	name VARCHAR(100), 
	dosage VARCHAR(60), 
	start_date DATE, 
	end_date DATE, 
	reminder_time VARCHAR(5), 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_medicines_patient_id ON medicines (patient_id);

CREATE TABLE IF NOT EXISTS nutrition_tracking (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	log_date DATE NOT NULL, 
	entry_type VARCHAR(8) NOT NULL, 
	meal_type VARCHAR(12), 
	food_id INTEGER, 
	food_name VARCHAR(100), 
	servings FLOAT, 
	kcal FLOAT, 
	protein_g FLOAT, 
	carbs_g FLOAT, 
	fat_g FLOAT, 
	water_ml INTEGER, 
	logged_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_nutrition_tracking_log_date ON nutrition_tracking (log_date);
CREATE INDEX ix_nutrition_tracking_patient_id ON nutrition_tracking (patient_id);

CREATE TABLE IF NOT EXISTS chatbot_messages (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	conversation_id INTEGER NOT NULL, 
	`role` VARCHAR(10) NOT NULL, 
	content TEXT NOT NULL, 
	language VARCHAR(5), 
	is_emergency BOOL, 
	meta JSON, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(conversation_id) REFERENCES chatbot_conversations (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_chatbot_messages_conversation_id ON chatbot_messages (conversation_id);
CREATE INDEX ix_chatbot_messages_created_at ON chatbot_messages (created_at);

CREATE TABLE IF NOT EXISTS diet_meals (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	plan_id INTEGER NOT NULL, 
	day_index INTEGER NOT NULL, 
	meal_type VARCHAR(12) NOT NULL, 
	items JSON, 
	kcal FLOAT, 
	protein_g FLOAT, 
	carbs_g FLOAT, 
	fat_g FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(plan_id) REFERENCES diet_plans (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_diet_meals_plan_id ON diet_meals (plan_id);

CREATE TABLE IF NOT EXISTS extracted_report_values (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	report_id INTEGER NOT NULL, 
	param_key VARCHAR(40) NOT NULL, 
	param_name VARCHAR(80), 
	value FLOAT NOT NULL, 
	unit VARCHAR(30), 
	ref_low FLOAT, 
	ref_high FLOAT, 
	ref_text VARCHAR(60), 
	status VARCHAR(20), 
	status_source VARCHAR(20), 
	raw_line VARCHAR(255), 
	PRIMARY KEY (id), 
	FOREIGN KEY(report_id) REFERENCES medical_reports (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_extracted_report_values_param_key ON extracted_report_values (param_key);
CREATE INDEX ix_extracted_report_values_report_id ON extracted_report_values (report_id);

CREATE TABLE IF NOT EXISTS prediction_inputs (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	prediction_id INTEGER NOT NULL, 
	feature_name VARCHAR(40) NOT NULL, 
	feature_value FLOAT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(prediction_id) REFERENCES disease_predictions (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX ix_prediction_inputs_prediction_id ON prediction_inputs (prediction_id);

SET FOREIGN_KEY_CHECKS = 1;